     "type": "context",
     "context": "Жүрек – адам ағзасындағы ең маңызды және үздіксіз жұмыс істейтін мүшелердің бірі. Оның негізгі қызметі – қанайналымды қамтамасыз ету арқылы дененің барлық жасушаларын оттегі және қоректік заттармен қамтамасыз ету. Бұл күрделі міндетті орындау үшін жүрек ерекше қасиетке ие – ол автоматия, яғни автономды (өздігінен) жұмыс істеу қабілеті.<br><br>Жүректің автономиясы – бұл жүрек бұлшықеттерінің сыртқы жүйке импульстарынсыз да ырғақты жиырылу қасиеті. Бұл қасиет жүректің өткізгіш жүйесі арқылы жүзеге асады. Өткізгіш жүйенің негізгі бөлігі – синатриалды (СА) түйін, ол жүрек соғысының табиғи ырғақ бастауы болып табылады. Бұл түйін өздігінен электр импульстарын шығара алады, бұл импульстар жүрекшелер мен қарыншалар арқылы таралып, жүректің ретті түрде жиырылуын қамтамасыз етеді.",
